// === Tab: Program definitions ===
function Program(a, b, c, d, tx, ty, updater, color, originX = 0, originY = 0){
	this.a = a;
	this.b = b;
	this.c = c;
	this.d = d;
	this.tx = tx;
	this.ty = ty;
	this.time = new Coord(this.tx, this.ty);
	this.origin = new Coord(originX, originY);
	this.color = color;
	this.color.setAlpha(8);
	this.updater = updater;
	this.update = function(){
		this.time = this.updater.updateTime(this);
		this.origin = this.updater.updateOrigin(this);
		stroke(this.color);
		this.origin.show();
	}
	return this;
}

updateA = {
	updateTime:function(program){
	let t2 = new Coord(program.time.x, program.time.y)
	t2.x+= ((program.tx * cos(program.tx*program.time.x+program.time.y) -program.tx * cos(program.ty*program.time.x+program.time.y)));
	t2.y+= ((program.ty * sin(program.ty*program.time.y+program.time.x) -program.ty * sin(program.tx*program.time.y+program.time.x)));
	return t2;
	},
	updateOrigin:function(program){
		let c2 = new Coord(program.origin.x, program.origin.y);
		c2.x = program.a * cos(program.time.x - program.origin.x * program.a) + program.b * sin(program.time.y - program.origin.y * program.b);
		c2.y = program.c * cos(program.time.x + program.origin.y * program.c) - program.d * sin(program.time.y + program.origin.x * program.d);
		return c2;
	}
}

updateB = {
	updateTime:function(program){
	var t2 = new Coord(program.time.x, program.time.y)
	t2.x+= program.time.x;
	t2.y+= program.time.y;
	return t2;
	},
	updateOrigin:function(program){
		var c2 = new Coord(program.origin.x, program.origin.y);
		c2.x = program.a * cos(program.time.x - program.origin.x * program.a) * program.b * sin(program.time.y - program.origin.y * program.b);
		c2.y = program.c * cos(program.time.x + program.origin.y * program.c) * program.d * sin(program.time.y + program.origin.x * program.d);
		return c2;
	}
}

updateC = {
	updateTime:function(program){
	var t2 = new Coord(randOne(program.time.x), randOne(program.time.y))
	t2.x+= program.tx;
	t2.y+= program.ty;
	return t2;
	},
	updateOrigin:function(program){
		var c2 = new Coord(program.origin.x, program.origin.y);
		c2.x = program.a * cos(program.time.x + program.origin.x / program.a) + program.b * sin(program.time.y + program.origin.y / program.b);
		c2.y = program.c * cos(program.time.x + program.origin.y / program.c) - program.d * sin(program.time.y + program.origin.x / program.d);
		return c2;
	}
}

updateD = {
	updateTime:function(program){
	var t2 = new Coord(program.time.x, program.time.y);
	t2.x+= program.tx*cos(program.time.x*program.tx)*(sin(program.time.y));
	t2.y+= program.ty*sin(program.time.y*program.ty)*(cos(program.time.x));
	return t2;
	},
	updateOrigin:function(program){
		var c2 = new Coord(program.origin.x, program.origin.y);
		c2.x = program.a * cos(program.time.x - program.origin.x * program.a) - program.b * atan(program.time.y - program.origin.y * program.b);
		c2.y = program.c * cos(program.time.x + program.origin.y * program.c) - program.d * atan(program.time.y + program.origin.x * program.d);
		return c2;
	}
}

class Coord{
	constructor(x, y){
		this.x = x;
		this.y = y;
	}

	show(scale=imageScale){
		point(scale*this.x, scale*this.y);
	}
}

